```c++
#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int main() {
  string word; // word to search for
  string line; // current line from the file
  int count = 0; // number of occurrences

  cout << "Enter the word to search for: ";
  cin >> word;

  // open the file for reading
  ifstream file("file.txt");
  if (!file.is_open()) {
    cout << "Error opening file" << endl;
    return 1;
  }

  // read the file line by line
  while (getline(file, line)) {
    // check if the word is in the line
    if (line.find(word) != string::npos) {
      count++;
    }
  }

  // close the file
  file.close();

  // print the number of occurrences
  cout << "The word " << word << " occurred " << count << " times in the file" << endl;

  return 0;
}
```

